head.script:
scwin.t1_onclick = function() {
    widgetContainer1.setCols(2);
};
scwin.t2_onclick = function() {
    widgetContainer1.setCols(9);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    widgetContainer1.addWidgets({
        title: "widget0",
        src: null,
        scope: true,
        x: "0",
        y: 0,
        unitWidth: "03",
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        title: "widget1",
        src: null,
        scope: true,
        x: 0,
        y: 1,
        unitWidth: 4,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        title: "widget2",
        src: null,
        scope: true,
        x: 4,
        y: 1,
        unitWidth: 4,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        title: "widget3",
        src: null,
        scope: true,
        x: 0,
        y: 2,
        unitWidth: 4,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        title: "widget4",
        src: null,
        scope: true,
        x: 0,
        y: 3,
        unitWidth: 1,
        unitHeight: 1
    });
    window.scwin = {};
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
